create extension if not exists pgcrypto;
create table if not exists public.sales_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,sku text not null,week date not null,actual numeric(14,3) not null check(actual>=0),price numeric(14,4) check(price is null or price>=0),promo boolean,stockout boolean,channel text not null default '',location text not null default '',category text,brand text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,sku,week,channel,location));
create index if not exists sales_history_user_sku_week_idx on public.sales_history(user_id,sku,week);
create table if not exists public.forecast_results(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,sku text not null,period_start date not null,forecast numeric(14,3) not null check(forecast>=0),selected_model text not null,runner_up_model text not null,validation_wmape numeric(12,4),validation_mae numeric(14,4),bias_pct numeric(12,4),history_periods integer not null,computed_at timestamptz not null default now(),unique(user_id,sku,period_start));
create table if not exists public.import_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,file_name text not null,dataset_type text not null default 'historical_sales',import_mode text not null check(import_mode in ('upsert','append')),rows_received integer not null default 0,rows_saved integer not null default 0,rows_rejected integer not null default 0,created_at timestamptz not null default now());
alter table public.sales_history enable row level security; alter table public.forecast_results enable row level security; alter table public.import_history enable row level security;
drop policy if exists sales_owner_policy on public.sales_history; create policy sales_owner_policy on public.sales_history for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists forecast_owner_policy on public.forecast_results; create policy forecast_owner_policy on public.forecast_results for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists import_owner_policy on public.import_history; create policy import_owner_policy on public.import_history for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
grant select,insert,update,delete on public.sales_history to authenticated; grant select,insert,update,delete on public.forecast_results to authenticated; grant select,insert,update,delete on public.import_history to authenticated;